function rowDecode(row: string): string {
  let out = '';
  for (let i = 0; i < row.length; i += 2) out += row[i + 1].repeat(row.charCodeAt(i) - 32);
  return out;
}
export const ASSETS_ZCODE: AssetDef[] = PACKED.map(([id, frames]) => ({id, frames: frames.map(f => f.map(rowDecode))}));
